# Parse the graph edges
edges_text = context.split("The graph has the following edges:\n")[1].split("\n\nOperation:")[0]

# Build adjacency list
from collections import defaultdict, deque

adj = defaultdict(list)
for line in edges_text.strip().split('\n'):
    if ' -> ' in line:
        src, dst = line.split(' -> ')
        adj[src].append(dst)

# BFS from node 1679091c5a, find nodes at exactly depth 4
start = "1679091c5a"
target_depth = 4

# BFS tracking depth
queue = deque([(start, 0)])
visited = {start}
nodes_at_depth = {0: {start}}

while queue:
    node, depth = queue.popleft()
    if depth >= target_depth:
        continue
    for neighbor in adj[node]:
        if neighbor not in visited or depth + 1 < target_depth:
            # We need to track nodes at each specific depth
            new_depth = depth + 1
            if new_depth not in nodes_at_depth:
                nodes_at_depth[new_depth] = set()
            nodes_at_depth[new_depth].add(neighbor)
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, new_depth))

print("Nodes at each depth:")
for d in sorted(nodes_at_depth.keys()):
    print(f"Depth {d}: {sorted(nodes_at_depth[d])}")

if target_depth in nodes_at_depth:
    result = sorted(nodes_at_depth[target_depth])
    print(f"\nNodes at exactly depth {target_depth}: {result}")
else:
    print(f"\nNo nodes at depth {target_depth}")
```

